from pathlib import Pathimport numpy as npimport pandas as pdimport matplotlib.pyplot as plt# PathsPROJECT_ROOT = Path(__file__).resolve().parent.parentPROCESSED_DIR = PROJECT_ROOT / "data" / "processed"RESULTS_DIR = PROJECT_ROOT / "results"PROCESSED_DIR.mkdir(parents=True, exist_ok=True)RESULTS_DIR.mkdir(parents=True, exist_ok=True)ALTITUDE_FILE = (    PROCESSED_DIR    / "cirbe_2024_daily_altitude.csv")KP_FILE = (    PROCESSED_DIR    / "kp_daily_2024-04-01_to_2024-06-30.csv")MERGED_FILE = (    PROCESSED_DIR    / "cirbe_2024_daily_altitude_kp.csv")FIGURE_FILE = (    RESULTS_DIR    / "cirbe_2024_decay_kp.png")# Load CIRBE altitude datadef load_cirbe_data():    print("Loading CIRBE orbital data...")    if not ALTITUDE_FILE.exists():        raise FileNotFoundError(            f"Could not find:\n{ALTITUDE_FILE}\n"            "Run cirbe_orbital_analysis.py first."        )    df = pd.read_csv(ALTITUDE_FILE)    df["date"] = pd.to_datetime(        df["date"],        utc=True,        errors="coerce",    )    df["altitude_km"] = pd.to_numeric(        df["altitude_km"],        errors="coerce",    )    df = df.dropna(        subset=["date", "altitude_km"]    )    df = df.sort_values("date").copy()    if df.empty:        raise ValueError(            "No valid CIRBE altitude data found."        )    # Actual elapsed time between observations    df["time_difference_days"] = (        df["date"].diff().dt.total_seconds() / 86400    )    # Change in altitude    # Positive = altitude increased    # Negative = altitude decreased    df["altitude_change_km"] = (        df["altitude_km"].diff()    )    # Orbital decay rate    # Positive = altitude loss    df["orbital_decay_km_day"] = (        -df["altitude_change_km"]        / df["time_difference_days"]    )    df.loc[        df["time_difference_days"] <= 0,        "orbital_decay_km_day",    ] = np.nan    print(        f"Loaded {len(df)} CIRBE daily observations."    )    return df# downloaded Kp measurementsdef load_kp_data():    print("\nLoading GFZ Potsdam Kp data...")    if not KP_FILE.exists():        raise FileNotFoundError(            f"Could not find:\n{KP_FILE}\n"            "Run download_cirbe_kp.py first."        )    kp = pd.read_csv(KP_FILE)    kp["date"] = pd.to_datetime(        kp["date"],        utc=True,        errors="coerce",    )    kp["daily_max_kp"] = pd.to_numeric(        kp["daily_max_kp"],        errors="coerce",    )    kp = kp.dropna(        subset=["date", "daily_max_kp"]    )    kp = kp.sort_values("date")    print(        f"Loaded {len(kp)} daily Kp observations."    )    return kp# Merge CIRBE altitude and Kpdef merge_data(cirbe, kp):    print("\nMerging CIRBE altitude and Kp...")    merged = cirbe.merge(        kp[["date", "daily_max_kp"]],        on="date",        how="left",        validate="one_to_one",    )    # Kp >= 5 indicates geomagnetic storm    merged["storm_day"] = (        merged["daily_max_kp"] >= 5    )    merged.to_csv(        MERGED_FILE,        index=False,    )    print(        f"Saved merged data to:\n{MERGED_FILE}"    )    return merged# Compare storm and quiet daysdef summarize_storm(merged):    print("\n" + "=" * 50)    print("CIRBE MAY 2024 STORM ANALYSIS")    print("=" * 50)    # Focus on May 1-21    start = pd.Timestamp(        "2024-05-01", tz="UTC"    )    end = pd.Timestamp(        "2024-05-21", tz="UTC"    )    may = merged[        (merged["date"] >= start)        & (merged["date"] <= end)    ].copy()    print("\nDaily orbital decay and Kp:\n")    print(        may[            [                "date",                "altitude_km",                "orbital_decay_km_day",                "daily_max_kp",                "storm_day",            ]        ].to_string(index=False)    )    # Remove missing measurements    valid = may.dropna(        subset=[            "orbital_decay_km_day",            "daily_max_kp",        ]    )    # Separate storm and quiet days    storm = valid[        valid["daily_max_kp"] >= 5    ]    quiet = valid[        valid["daily_max_kp"] < 5    ]    print("\n" + "-" * 50)    print(f"Storm-day observations: {len(storm)}")    print(f"Quiet-day observations: {len(quiet)}")    # Mean orbital decay during storms    storm_mean = (        storm["orbital_decay_km_day"].mean()    )    # Mean orbital decay during quiet conditions    quiet_mean = (        quiet["orbital_decay_km_day"].mean()    )    print(        f"\nMean storm-day decay: "        f"{storm_mean:.4f} km/day"    )    print(        f"Mean quiet-day decay: "        f"{quiet_mean:.4f} km/day"    )    # Percentage difference    if (        pd.notna(storm_mean)        and pd.notna(quiet_mean)        and quiet_mean > 0    ):        percent_increase = (            (storm_mean - quiet_mean)            / quiet_mean * 100        )        print(            f"Storm vs quiet difference: "            f"{percent_increase:.2f}%"        )    else:        print(            "Not enough valid measurements "            "to calculate percentage difference."        )    # Pearson correlation    if (        len(valid) >= 3        and valid["daily_max_kp"].nunique() > 1        and valid["orbital_decay_km_day"].nunique() > 1    ):        correlation = valid[            [                "daily_max_kp",                "orbital_decay_km_day",            ]        ].corr(method="pearson").iloc[0, 1]        print(            f"\nPearson correlation (r): "            f"{correlation:.4f}"        )    else:        print(            "\nNot enough measurements "            "to calculate Pearson correlation."        )def plot_decay_kp(merged):    start = pd.Timestamp(        "2024-05-01", tz="UTC"    )    end = pd.Timestamp(        "2024-05-22", tz="UTC"    )    may = merged[        (merged["date"] >= start)        & (merged["date"] < end)    ].copy()    fig, (ax1, ax2) = plt.subplots(        2,        1,        figsize=(12, 9),        sharex=True,    )     ax1.plot(        may["date"],        may["orbital_decay_km_day"],        color="navy",        marker="o",        linewidth=1.8,        label="CIRBE daily orbital decay",    )    ax1.axhline(        0,        color="gray",        linestyle=":",    )    ax1.set_ylabel(        "Orbital Decay (km/day)"    )    ax1.set_title(        "CIRBE Orbital Decay and Geomagnetic "        "Activity: May 2024"    )    ax1.legend()    ax1.grid(alpha=0.3)    ax2.bar(        may["date"],        may["daily_max_kp"],        width=0.8,        color="steelblue",        label="Daily maximum Kp",    )    ax2.axhline(        5,        color="red",        linestyle="--",        label="Kp = 5 storm threshold",    )    ax2.set_ylabel("Daily Maximum Kp")    ax2.set_xlabel("Date")    ax2.set_ylim(0, 9.5)    ax2.legend()    ax2.grid(alpha=0.3)    # Highlight May 10-13 storm    storm_start = pd.Timestamp(        "2024-05-10", tz="UTC"    )    storm_end = pd.Timestamp(        "2024-05-14", tz="UTC"    )    for ax in (ax1, ax2):        ax.axvspan(            storm_start,            storm_end,            color="red",            alpha=0.12,        )    fig.autofmt_xdate()    plt.tight_layout()    plt.savefig(        FIGURE_FILE,        dpi=300,        bbox_inches="tight",    )    print(        f"\nSaved comparison figure to:\n"        f"{FIGURE_FILE}"    )    plt.show()# Maindef main():    # Load CIRBE daily orbital altitude    cirbe = load_cirbe_data()    # Load previously downloaded Kp data    kp = load_kp_data()    # Merge the two datasets    merged = merge_data(cirbe, kp)    # Compare storm and quiet days    summarize_storm(merged)    # Generate comparison graph    plot_decay_kp(merged)    print("\nCIRBE Kp analysis complete!")if __name__ == "__main__":    main()